// freshCompletePadding clears nested complete-value padding for an explicit
// fresh encoding (X.691 (02/2021) §§11.1.4, 11.2.1).
func X2apInternalFreshCompletePadding(padding aper.CompletePadding, fresh ...bool) aper.CompletePadding {
	if len(fresh) != 0 && fresh[0] {
		return aper.CompletePadding{}
	}
	return padding
}

// preferredSequenceTail chooses the shortest extension bitmap containing all
// semantic additions. X.691 (02/2021) §19.8 defines its index and length.
func X2apInternalPreferredSequenceTail(present []bool, data [][]byte) (int64, bool) {
	var last int64
	found := false
	for i, set := range present {
		if set {
			last = int64(i)
			found = true
		}
	}
	for i, contents := range data {
		if contents != nil {
			last = int64(i)
			found = true
		}
	}
	return last, found
}
func X2apInternalReceivedFormAt(present bool, original aper.WireSpan, path aper.Path, location aper.Location, complete interface{ Bits() (uint8, uint8) }) aper.ReceivedForm {
	location.Path = path
	var padding []aper.PaddingSpan
	if location.HasWireLocation && len(location.Spans) != 0 {
		last := location.Spans[len(location.Spans)-1]
		value, count := complete.Bits()
		width, borrow := bits.Sub64(last.End, last.Start, 0)
		if count != 0 && borrow == 0 && uint64(count) <= width {
			start, borrow := bits.Sub64(last.End, uint64(count), 0)
			if borrow == 0 {
				padding = []aper.PaddingSpan{{Span: aper.BitSpan{Start: start, End: last.End}, Value: value, Width: count}}
			}
		}
	}
	return aper.NewReceivedSpanForm(present, original, location, padding)
}

