type ValidationCode uint8

const (
	MissingMandatory ValidationCode = iota + 1
	NotAllowed
	WrongCriticality
	RepeatedIE
	WrongOrder
	UnknownProcedure
	UnavailableOutcome
	ValueIDMismatch
)

type ValidationSeverity uint8

const (
	ValidationSeverityError ValidationSeverity = iota + 1
	ValidationSeverityUnrecognized
	ValidationSeverityInformational
)

func X2apInternalX2apValidationRule(code ValidationCode) aper.SourceRule {
	_ = code
	return aper.SourceRule{Document: "3GPP TS 36.423", Edition: "V19.1.0", Clause: "§10"}
}

// TS 36.413 V19.2.0 §10.3.4.2 supplies receiver handling, not the
// identifier-membership severity policy. §10.3.4.1A handles message type.
func X2apInternalX2apHandlingRules(code ValidationCode) []aper.SourceRule {
	rules := []aper.SourceRule{X2apInternalX2apAdoptedRule(code)}
	clause := ""
	switch code {
	case NotAllowed:
		clause = "§10.3.4.2"
	case UnavailableOutcome:
		clause = "§10.3.4.1A"
	}
	if clause != "" {
		rules = append(rules, aper.SourceRule{Document: "3GPP TS 36.413", Edition: "V19.2.0", Clause: clause})
	}
	return rules
}
func X2apInternalX2apAdoptedRule(code ValidationCode) aper.SourceRule {
	clause := "§10"
	switch code {
	case MissingMandatory:
		clause = "§10.3.5"
	case NotAllowed:
		clause = "§10.3.1"
	case WrongCriticality:
		clause = "§10.3.2"
	case RepeatedIE, WrongOrder:
		clause = "§10.3.6"
	case UnknownProcedure, UnavailableOutcome:
		clause = "§10.3.4.1"
	}
	return aper.SourceRule{Document: "3GPP TS 36.413", Edition: "V19.2.0", Clause: clause}
}

